Loops in C++ Are Fast
A loop-heavy statistic: the random walk Metropolis sampler for a \(N(0,1)\) target.

cppFunction("
NumericVector rwMetropolisC(double sigma, double x0, int N) {
  NumericVector x(N); x[0] = x0;
  NumericVector u = runif(N);
  for (int i = 1; i &lt; N; i++) {
    double y = R::rnorm(x[i - 1], sigma);
    if (u[i] &lt;= exp(-0.5 * (y * y - x[i - 1] * x[i - 1]))) x[i] = y; else x[i] = x[i - 1];
  }
  return x;
}")
rwMetropolisR &lt;- function(sigma, x0, N) {
  x &lt;- numeric(N); x[1] &lt;- x0; u &lt;- runif(N)
  for (i in 2:N) { y &lt;- rnorm(1, x[i - 1], sigma)
    x[i] &lt;- if (u[i] &lt;= exp(-0.5 * (y^2 - x[i - 1]^2))) y else x[i - 1] }
  x
}
